\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{booktabs}
\pagestyle{empty}

% ══ IMF Color Theme ══
\definecolor{primary}{HTML}{002244}
\definecolor{secondary}{HTML}{1A4472}
\definecolor{accent}{HTML}{D4760A}
\definecolor{bgposter}{HTML}{EEF2F7}
\definecolor{darkbg}{HTML}{E8EEF5}
\definecolor{redbg}{HTML}{FFF6EF}
\definecolor{bluebg}{HTML}{F0F4FB}
\definecolor{darktitlebg}{HTML}{D4DEEC}
\definecolor{redtitlebg}{HTML}{FDE8D4}
\definecolor{bluetitlebg}{HTML}{DAE2F2}
\definecolor{textdark}{HTML}{111827}
\definecolor{textgray}{HTML}{4B5563}
\definecolor{stathighlight}{HTML}{FEF0E0}
\definecolor{riskred}{HTML}{C53030}

\pagecolor{bgposter}
\color{textdark}

% ══ List styling ══
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{accent}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=28pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ══ Figure+caption macro ══
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{24}{30}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ══ Card styles (left accent stripe) ══
\tcbset{
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=redtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.18},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=bluetitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!18!white,
    borderline west={6pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.22},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ═══════════════════════════════════════════
% TITLE BAR
% ═══════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=18pt, bottom=10pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{72}{88}\selectfont\bfseries Global Economy in the Shadow of War}\\[14pt]
  {\fontsize{38}{46}\selectfont IMF World Economic Outlook Trends 2024--2026}\\[14pt]
  {\fontsize{30}{38}\selectfont\color{white!75} IMF--World Bank Annual Meetings Research Symposium \quad$\mid$\quad 2026}
}

% ═══════════════════════════════════════════
% STATS BANNER
% ═══════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!12!white, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=6pt, bottom=6pt,
  valign=center, borderline south={3pt}{0pt}{primary!30},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{accent!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{62}{76}\selectfont\bfseries\color{accent} 3.0\%}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textdark} Global Growth 2025}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{62}{76}\selectfont\bfseries\color{primary} 3.3\%}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textdark} Global Growth 2026}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{riskred!40}{riskred!12!white}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{42}{52}\selectfont\bfseries\color{riskred} 8}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textdark} WEO Editions Reviewed}\\[2pt]
      {\fontsize{20}{26}\selectfont\bfseries\color{riskred} All Tilted Downside}\vspace{8pt}%
    }}
  \end{minipage}
}

% ═══════════════════════════════════════════
% ROW A: Growth Trajectory (HERO, span 2) + Key Risks
% ═══════════════════════════════════════════
\posterbox[darkcard, title={Global Growth: A Narrow Band of Mediocrity}
]{name=growth, column=1, span=2, between=row6 and row12}{
  \posterfig{0.98}{figures/growth_trajectory.png}{IMF global growth projections across eight WEO editions, Jul 2024--Apr 2026. The 3.0--3.3\% band sits well below the pre-pandemic average of 3.8\%.}
  \vspace{2mm}
  \colorbox{primary!20}{\parbox{0.94\linewidth}{%
    \fontsize{30}{38}\selectfont
    \textbf{\color{primary}Key finding:} Global growth stuck in a narrow 3.0--3.3\% band across all eight editions---persistently below the pre-pandemic 3.8\% average.
  }}
}

\posterbox[redcard, title={Dominant Downside Risks}
]{name=risks, column=3, span=1, between=row6 and row12}{
  \posterfig{0.96}{figures/risk_landscape.png}{Risk factor frequency across 8 WEO editions.}
  \vspace{2mm}
  \fontsize{30}{38}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item \textbf{Trade policy} escalation---tariff front-loading masks damage
    \item \textbf{Geopolitical tensions}---conflicts, security concerns
    \item \textbf{Tech re-evaluation}---AI hype correction risk
    \item \textbf{Sticky services inflation}---US especially slow to target
  \end{itemize}
  \vspace{4mm}
  \colorbox{riskred!18}{\parbox{0.94\linewidth}{%
    \fontsize{30}{38}\selectfont
    \textbf{\color{riskred}Risk balance tilted to the downside} in every single WEO edition---the most persistent finding.
  }}
}

% ═══════════════════════════════════════════
% ROW B: Policy Evolution (span 2) + Inflation
% ═══════════════════════════════════════════
\posterbox[bluecard, title={Evolving Policy Priorities}
]{name=policy, column=1, span=2, between=row12 and row16}{
  \posterfig{0.96}{figures/policy_evolution.png}{IMF policy recommendations evolved from monetary management to defense-spending trade-offs.}
  \vspace{2mm}
  \fontsize{30}{38}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item \textbf{2024:} Manage disinflation $\to$ pivot monetary policy; fiscal sustainability
    \item \textbf{Early 2025:} Rebuild fiscal buffers; address demographic and gender gaps
    \item \textbf{Late 2025:} Strengthen frameworks; cautious industrial policy
    \item \textbf{2026:} Agile policy; manage \textbf{defense-spending trade-offs}
  \end{itemize}
}

\posterbox[redcard, title={Inflation \& Monetary Policy}
]{name=inflation, column=3, span=1, between=row12 and row16}{
  \posterfig{0.96}{figures/inflation_dynamics.png}{Projected inflation vs.\ central bank targets by economy group.}
  \vspace{2mm}
  \fontsize{30}{38}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item Global headline inflation declining through 2026
    \item \textbf{US exception:} above target longer than peers
    \item Services inflation sticky, slowing disinflation
    \item Renewed pressure by Apr 2026 from defense spending
  \end{itemize}
}

% ═══════════════════════════════════════════
% ROW C: Themes + Data Table + Key Takeaways
% ═══════════════════════════════════════════
\posterbox[bluecard, title={Special Analytical Themes}
]{name=themes, column=1, span=1, between=row16 and row20}{
  \fontsize{30}{38}\selectfont
  \begin{enumerate}[itemsep=10pt]
    \item \textbf{Industrial policy}---effectiveness and fiscal cost
    \item \textbf{Social acceptability} of structural reforms
    \item \textbf{Demographic challenges}---aging populations
    \item \textbf{Gender \& migration}---labor market integration
  \end{enumerate}
  \vspace{4mm}
  \colorbox{secondary!20}{\parbox{0.94\linewidth}{%
    \fontsize{28}{36}\selectfont
    IMF's lens broadens beyond macro stabilization toward inclusive and sustainable growth strategies.
  }}
}

\posterbox[darkcard, title={Growth Projections Data}
]{name=datatable, column=2, span=1, between=row16 and row20}{
  \fontsize{28}{36}\selectfont
  \centering
  \renewcommand{\arraystretch}{1.5}
  \begin{tabular}{lc}
    \toprule
    \rowcolor{primary!15}
    \textbf{WEO Edition} & \textbf{2025 Growth} \\
    \midrule
    Jul 2024 & 3.3\% \\
    Oct 2024 & 3.3\% \\
    Jan 2025 & 3.3\% \\
    \rowcolor{accent!15}
    Apr 2025 & Slowing \\
    \rowcolor{riskred!12}
    Jul 2025 & \textbf{3.0\%} \\
    Oct 2025 & Slowing \\
    Jan 2026 & 3.3\% \\
    \rowcolor{riskred!12}
    Apr 2026 & Slowing \\
    \bottomrule
  \end{tabular}
  \vspace{3mm}
  {\fontsize{24}{30}\selectfont\color{textgray}\textit{Pre-pandemic avg: 3.8\%}}
}

\posterbox[highlightcard, title={Key Takeaways}
]{name=takeaways, column=3, span=1, between=row16 and row20}{
  \fontsize{32}{40}\selectfont\color{primary}
  \begin{enumerate}[itemsep=12pt]
    \item \textbf{Persistent mediocrity}---growth stuck at 3.0--3.3\%, far below historical norms
    \item \textbf{Growing fragility}---risks consistently tilted downside across all 8 editions
    \item \textbf{Policy evolution}---from monetary pivot to defense-spending trade-offs signals new era
  \end{enumerate}
  \vspace{4mm}
  \colorbox{accent!25}{\parbox{0.94\linewidth}{%
    \fontsize{28}{36}\selectfont
    \textbf{\color{accent}The global economy is not collapsing---but it is not recovering either, and the risk balance is consistently tilted to the downside.}
  }}
}

\end{tcbposter}
\end{document}

